        int seriesCount = dataset.getSeriesCount();
        for (int i = 0; i < seriesCount; i++) {
            if (renderer.isSeriesVisible(i)
                    && renderer.isSeriesVisibleInLegend(i)) {
                LegendItem item = renderer.getLegendItem(datasetIndex, i);
                if (item != null) {
                    items.add(item);
                }
            }
        }
    }
}


